    const response1 = await createCollection(page, getValue(playwrightRequest1, "collection"));
    expect(response1.status()).toBe(200);
    expect(getValue(await response1.text(), "data.collection")).toBe(getValue(playwrightRequest1, "collection"));

    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await page.getByRole("link").nth(3).click();
    await expect(page).toHaveURL(`${baseUrl}/admin/content/${getValue(playwrightRequest1, "collection")}`);
    await expect(emptyCollections).toHaveCount(0);
    await expect(page.locator("#module-navigation").getByRole("link")).toHaveCount(1);
    await expect(page.locator("#module-navigation").getByRole("link")).toContainText("Qa Empty State");

    const url0 = `${baseUrl}/admin/settings/data-model/${getValue(await response1.text(), "data.schema.name")}`;
